public class AutoOptionsListener<R> : OptionsChangeListener {
	protected static readonly Map<Class<object>, Set<OptionSetter<object>>> SETTERS_BY_RECEIVER_CLASS =
		new();
	protected static readonly Map<Class<object>, ReceiverProfile<object>> PROFILES_BY_RECEIVER_CLASS =
		new();

	protected interface OptionSetter<R> {
