	protected class ParamOrder
{	public static readonly ParamOrder NONE = new((o, n);
	public static readonly ParamOrder NEW_ONLY = new((o, n);
	public static readonly ParamOrder OLD_ONLY = new((o, n);
	public static readonly ParamOrder NEW_OLD = new((o, n);
	public static readonly ParamOrder OLD_NEW = new((o, n);


		private BiFunction<object, object, object[]> pop;

		ParamOrder(BiFunction<object, object, object[]> pop) {
			this.pop = pop;
		}

		public object[] populate(object oldVal, object newVal) {
			return this.pop.apply(oldVal, newVal);
		}
	}

	protected static class MethodOptionSetter<R> : OptionSetter<R> {
		protected Method method;
		protected CategoryAndName key;
		protected ParamOrder order;

		public MethodOptionSetter(Method method, AutoOptionConsumed annotation, Plugin plugin) : this(method, new CategoryAndName(annotation, plugin))
    {
		}

		public MethodOptionSetter(Method method, string category, string name) : this(method, new CategoryAndName(category, name))
    {
		}

		public MethodOptionSetter(Method method, CategoryAndName key) {
			this.method = method;
			this.key = key;

			method.setAccessible(true);

			Parameter[] parameters = method.getParameters();
			if (parameters.length == 0) {
				this.order = ParamOrder.NONE;
			}
			else if (parameters.length == 1) {
				if (parameters[0].getAnnotation(typeof(OldValue)) != null) {
					this.order = ParamOrder.OLD_ONLY;
				}
				else {
					this.order = ParamOrder.NEW_ONLY;
				}
			}
			else if (parameters.length == 2) {
				if (parameters[0].getAnnotation(typeof(NewValue)) != null) {
					if (parameters[1].getAnnotation(typeof(NewValue)) != null) {
						throw new IllegalArgumentException("Cannot apply " +
							typeof(NewValue).getName() + " to both parameters of " + method);
					}
					this.order = ParamOrder.NEW_OLD;
				}
				else if (parameters[0].getAnnotation(typeof(OldValue)) != null) {
					if (parameters[1].getAnnotation(typeof(OldValue)) != null) {
						throw new IllegalArgumentException("Cannot apply " +
							typeof(OldValue).getName() + " to both parameters of " + method);
					}
					this.order = ParamOrder.OLD_NEW;
				}
				else {
					if (parameters[1].getAnnotation(typeof(NewValue)) != null) {
						this.order = ParamOrder.OLD_NEW;
					}
					else {
						this.order = ParamOrder.NEW_OLD;
					}
				}
			}
			else {
				throw new IllegalArgumentException(typeof(AutoOptionConsumed) + "-annotated method " +
					method + " cannot have more than two parameters");
			}
		}

		/* @Override */
		public void set(R receiver, object newValue, object oldValue) {
			object[] args = order.populate(oldValue, newValue);
			try {
				method.invoke(receiver, args);
			}
			catch (Exception e) when (e is IllegalArgumentException or IllegalAccessException) {
				string argsStr = StringUtils.join(args, ",");
				// Don't throw, so other consumers get updated
				Msg.error(this,
					"Could not invoke " + method + "(" + argsStr + ") for option " + key, e);
			}
			catch (InvocationTargetException e) {
				Throwable cause = e.getCause();
				if (cause is RuntimeException) {
					throw (RuntimeException) cause;
				}
				string argsStr = StringUtils.join(args, ",");
				// Don't throw, so other consumers get updated
				Msg.error(this,
					"Error during invocation of " + method + "(" + argsStr + ") for option " + key,
					e.getCause());
			}
		}

		/* @Override */
		public CategoryAndName getKey() {
			return key;
		}
	}

	protected static class ReceiverProfile<R> {
		protected Map<CategoryAndName, Set<OptionSetter<R>>> settersByOption =
			new();

		protected Set<string> categories = new();
		protected Set<string> categoriesView = Collections.unmodifiableSet(categories);

		/* @SuppressWarnings({ "rawtypes", "unchecked" }) */
		public ReceiverProfile(Class<R> receiverCls, Plugin plugin) {
			foreach (OptionSetter<object> setter in collectSettersByReceiver(receiverCls, plugin)) {
				CategoryAndName key = setter.getKey();
				Set<OptionSetter<R>> settersForReceiver =
					settersByOption.computeIfAbsent(key, k => new());
				settersForReceiver.add((OptionSetter) setter);
				categories.add(key.category());
			}
		}

		public void optionsChanged(ToolOptions options, string optionName, object oldValue,
				object newValue, R receiver) {
			if (oldValue == null) {
				// TODO: Wish Ghidra would give default as old value, in case null was actual value
				// Maybe Ghidra does not allow null?
				oldValue = options.getDefaultValue(optionName);
			}
			CategoryAndName key = new CategoryAndName(options.getName(), optionName);
			Set<OptionSetter<R>> settersForOption = settersByOption.get(key);
			if (settersForOption == null) {
				return; // Receiver does not consume this option
			}
			foreach (OptionSetter<R> setter in settersForOption) {
				setter.set(receiver, newValue, oldValue);
			}
		}

		public void notifyCurrentValues(PluginTool tool, R receiver) {
			foreach (Map.Entry<CategoryAndName, Set<OptionSetter<R>>> ent in settersByOption
					.entrySet()) {
				CategoryAndName key = ent.getKey();
				ToolOptions options = tool.getOptions(key.category());
				Option opt = options.getOption(key.name(), OptionType.NO_TYPE, null);
				if (!opt.isRegistered()) {
					continue;
				}
				object newValue = opt.getValue(null);
				object oldValue = opt.getDefaultValue();

				foreach (OptionSetter<R> setter in ent.getValue()) {
					setter.set(receiver, newValue, oldValue);
				}
			}
		}
	}

	/* @SuppressWarnings({ "rawtypes", "unchecked" }) */
	protected static Set<OptionSetter<R>> collectSettersByReceiver<R>(Class<R> cls,
			Plugin plugin) {
		lock (SETTERS_BY_RECEIVER_CLASS) {
			if (SETTERS_BY_RECEIVER_CLASS.containsKey(cls)) {
				return (Set) SETTERS_BY_RECEIVER_CLASS.get(cls);
			}

			Set<OptionSetter<object>> result = new();
			SETTERS_BY_RECEIVER_CLASS.put(cls, result);

			Class<object> superclass = cls.getSuperclass();
			if (superclass != null) {
				Set<OptionSetter<object>> superResult =
					(Set) collectSettersByReceiver(superclass, plugin);
				result.addAll(superResult);
			}

			foreach (Class<object> superiface in cls.getInterfaces()) {
				Set<OptionSetter<object>> superResult =
					(Set) collectSettersByReceiver(superiface, plugin);
				result.addAll(superResult);
			}

			foreach (Field f in cls.getDeclaredFields()) {
				AutoOptionDefined defined = f.getAnnotation(typeof(AutoOptionDefined));
				if (defined != null) {
					try {
						result.add(new FieldOptionSetter(f, defined, plugin));
					}
					catch (IllegalArgumentException e) {
						Msg.error(typeof(AutoOptionsListener), e.getMessage());
					}
				}
				AutoOptionConsumed consumed = f.getAnnotation(typeof(AutoOptionConsumed));
				if (consumed != null) {
					try {
						// TODO: Validate type compatibility
						// Potential problem: consumed options may be registered yet
						result.add(new FieldOptionSetter(f, consumed, plugin));
					}
					catch (IllegalArgumentException e) {
						Msg.error(typeof(AutoOptionsListener), e.getMessage());
					}
				}
			}

			foreach (Method m in cls.getDeclaredMethods()) {
				AutoOptionConsumed consumed = m.getAnnotation(typeof(AutoOptionConsumed));
				if (consumed == null) {
					continue;
				}
				try {
					result.add(new MethodOptionSetter(m, consumed, plugin));
				}
				catch (IllegalArgumentException e) {
					Msg.error(typeof(AutoOptionsListener), e.getMessage());
				}
			}

			return (Set) result;
		}
	}

	protected R receiver;
	protected ReceiverProfile<R> profile;

	/* @SuppressWarnings("unchecked") */
	public AutoOptionsListener(Plugin plugin, R receiver) {
		this.receiver = receiver;
		this.profile = (ReceiverProfile<R>) PROFILES_BY_RECEIVER_CLASS
				.computeIfAbsent(receiver.GetType(), cls => new(cls, plugin));
	}

	/* @Override */
	public void optionsChanged(ToolOptions options, string optionName, object oldValue,
			object newValue) {
		profile.optionsChanged(options, optionName, oldValue, newValue, receiver);
	}

	public void notifyCurrentValues(PluginTool tool) {
		profile.notifyCurrentValues(tool, receiver);
	}

	public Set<string> getCategories() {
		return profile.categoriesView;
	}
